SELECT analytics_order_facts.quarter, SUM(analytics_order_facts.net_revenue) AS net_revenue FROM analytics_order_facts WHERE analytics_order_facts.year IN (2025, 2026) AND analytics_order_facts.region = 'South' AND analytics_order_facts.channel = 'online' AND analytics_order_facts.customer_segment = 'mid_market' AND analytics_order_facts.category = 'category_01' GROUP BY analytics_order_facts.quarter ORDER BY analytics_order_facts.quarter ASC LIMIT 24
